        { "utf-8-sig", "with open('report.bin','w',encoding='utf-8-sig',errors='strict',newline='\\r\\n') as target:\n    print('initial',target.tell())\n    for value in ['', 'A\\né', '€😀', '\\r\\nZ']:\n        before=target.tell()\n        try:\n            print('write',target.write(value),target.tell())\n        except UnicodeEncodeError as error:\n            print('error',error.start,error.end,error.object is value,target.tell()==before)\n        target.flush()\n        print('flushed',target.tell())\nwith open('report.bin','a',encoding='utf-8-sig',errors='strict',newline='\\r\\n') as target:\n    print('append',target.write('!'),target.tell())\nwith open('report.bin','rb') as result:\n    print(result.read().hex())\n", "initial 0\nwrite 0 3\nflushed 3\nwrite 3 8\nflushed 8\nwrite 2 15\nflushed 15\nwrite 3 19\nflushed 19\nappend 1 20\nefbbbf410d0ac3a9e282acf09f98800d0d0a5a21\n", "efbbbf410d0ac3a9e282acf09f98800d0d0a5a21" },
        { "utf-16", "with open('report.bin','w',encoding='utf-16',errors='strict',newline='\\r\\n') as target:\n    print('initial',target.tell())\n    for value in ['', 'A\\né', '€😀', '\\r\\nZ']:\n        before=target.tell()\n        try:\n            print('write',target.write(value),target.tell())\n        except UnicodeEncodeError as error:\n            print('error',error.start,error.end,error.object is value,target.tell()==before)\n        target.flush()\n        print('flushed',target.tell())\nwith open('report.bin','a',encoding='utf-16',errors='strict',newline='\\r\\n') as target:\n    print('append',target.write('!'),target.tell())\nwith open('report.bin','rb') as result:\n    print(result.read().hex())\n", "initial 0\nwrite 0 2\nflushed 2\nwrite 3 10\nflushed 10\nwrite 2 16\nflushed 16\nwrite 3 24\nflushed 24\nappend 1 26\nfffe41000d000a00e900ac203dd800de0d000d000a005a002100\n", "fffe41000d000a00e900ac203dd800de0d000d000a005a002100" },
        { "utf-16-le", "with open('report.bin','w',encoding='utf-16-le',errors='strict',newline='\\r\\n') as target:\n    print('initial',target.tell())\n    for value in ['', 'A\\né', '€😀', '\\r\\nZ']:\n        before=target.tell()\n        try:\n            print('write',target.write(value),target.tell())\n        except UnicodeEncodeError as error:\n            print('error',error.start,error.end,error.object is value,target.tell()==before)\n        target.flush()\n        print('flushed',target.tell())\nwith open('report.bin','a',encoding='utf-16-le',errors='strict',newline='\\r\\n') as target:\n    print('append',target.write('!'),target.tell())\nwith open('report.bin','rb') as result:\n    print(result.read().hex())\n", "initial 0\nwrite 0 0\nflushed 0\nwrite 3 8\nflushed 8\nwrite 2 14\nflushed 14\nwrite 3 22\nflushed 22\nappend 1 24\n41000d000a00e900ac203dd800de0d000d000a005a002100\n", "41000d000a00e900ac203dd800de0d000d000a005a002100" },
        { "utf-16-be", "with open('report.bin','w',encoding='utf-16-be',errors='strict',newline='\\r') as target:\n    print('initial',target.tell())\n    for value in ['', 'A\\né', '€😀', '\\r\\nZ']:\n        before=target.tell()\n        try:\n            print('write',target.write(value),target.tell())\n        except UnicodeEncodeError as error:\n            print('error',error.start,error.end,error.object is value,target.tell()==before)\n        target.flush()\n        print('flushed',target.tell())\nwith open('report.bin','a',encoding='utf-16-be',errors='strict',newline='\\r') as target:\n    print('append',target.write('!'),target.tell())\nwith open('report.bin','rb') as result:\n    print(result.read().hex())\n", "initial 0\nwrite 0 0\nflushed 0\nwrite 3 6\nflushed 6\nwrite 2 12\nflushed 12\nwrite 3 18\nflushed 18\nappend 1 20\n0041000d00e920acd83dde00000d000d005a0021\n", "0041000d00e920acd83dde00000d000d005a0021" },
        { "latin-1", "with open('report.bin','w',encoding='latin-1',errors='ignore',newline='\\r\\n') as target:\n    print('initial',target.tell())\n    for value in ['', 'A\\né', '€😀', '\\r\\nZ']:\n        before=target.tell()\n        try:\n            print('write',target.write(value),target.tell())\n        except UnicodeEncodeError as error:\n            print('error',error.start,error.end,error.object is value,target.tell()==before)\n        target.flush()\n        print('flushed',target.tell())\nwith open('report.bin','a',encoding='latin-1',errors='ignore',newline='\\r\\n') as target:\n    print('append',target.write('!'),target.tell())\nwith open('report.bin','rb') as result:\n    print(result.read().hex())\n", "initial 0\nwrite 0 0\nflushed 0\nwrite 3 4\nflushed 4\nwrite 2 4\nflushed 4\nwrite 3 8\nflushed 8\nappend 1 9\n410d0ae90d0d0a5a21\n", "410d0ae90d0d0a5a21" },
        { "ascii", "with open('report.bin','w',encoding='ascii',errors='strict',newline='\\r\\n') as target:\n    print('initial',target.tell())\n    for value in ['', 'A\\né', '€😀', '\\r\\nZ']:\n        before=target.tell()\n        try:\n            print('write',target.write(value),target.tell())\n        except UnicodeEncodeError as error:\n            print('error',error.start,error.end,error.object is value,target.tell()==before)\n        target.flush()\n        print('flushed',target.tell())\nwith open('report.bin','a',encoding='ascii',errors='strict',newline='\\r\\n') as target:\n    print('append',target.write('!'),target.tell())\nwith open('report.bin','rb') as result:\n    print(result.read().hex())\n", "initial 0\nwrite 0 0\nflushed 0\nerror 3 4 False True\nflushed 0\nerror 0 2 True True\nflushed 0\nwrite 3 4\nflushed 4\nappend 1 5\n0d0d0a5a21\n", "0d0d0a5a21" },
        { "cp1252", "with open('report.bin','w',encoding='cp1252',errors='backslashreplace',newline='\\r\\n') as target:\n    print('initial',target.tell())\n    for value in ['', 'A\\né', '€😀', '\\r\\nZ']:\n        before=target.tell()\n        try:\n            print('write',target.write(value),target.tell())\n        except UnicodeEncodeError as error:\n            print('error',error.start,error.end,error.object is value,target.tell()==before)\n        target.flush()\n        print('flushed',target.tell())\nwith open('report.bin','a',encoding='cp1252',errors='backslashreplace',newline='\\r\\n') as target:\n    print('append',target.write('!'),target.tell())\nwith open('report.bin','rb') as result:\n    print(result.read().hex())\n", "initial 0\nwrite 0 0\nflushed 0\nwrite 3 4\nflushed 4\nwrite 2 15\nflushed 15\nwrite 3 19\nflushed 19\nappend 1 20\n410d0ae9805c5530303031663630300d0d0a5a21\n", "410d0ae9805c5530303031663630300d0d0a5a21" },
    };

    [Theory]
    [MemberData(nameof(Cases))]
    public async Task EncodedStoragePreservesIncrementalPythonBehavior(string codec, string source, string expected, string hex)
    {
        var budget = new LythonMemoryBudget(2 * 1024 * 1024);
        using (var script = new LythonEngine().Compile(source, budget))
        {
            Assert.True(script.IsValid, codec + ": " + string.Join("; ", script.Diagnostics.Select(d => d.Message)));
            var baseline = budget.ReservedBytes;
            foreach (var asynchronous in new[] { false, true })
            {
                var host = new MockLythonHost();
                using (var result = asynchronous ? await script.RunAsync(host) : script.Run(host))
                {
                    Assert.True(result.Success, codec + ": " + result.Failure?.Message);
                    Assert.Equal(expected, result.StandardOutput);
                    Assert.Equal(Convert.FromHexString(hex), host.ReadBytes("/report.bin"));
                }
                Assert.Equal(baseline, budget.ReservedBytes);
            }
        }
        Assert.Equal(0, budget.ReservedBytes);
    }
}
